package com.huy.enterprise.product; import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.RecordStatus; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service @RequiredArgsConstructor @Transactional(readOnly=true) public class ProductService {private final ProductRepository repo;private final ProductCategoryRepository cats; Product entity(UUID id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Product not found: "+id));} @Transactional public ProductResponse create(ProductRequest r){if(repo.existsByProductCode(r.productCode()))throw new ConflictException("Product code already exists");return ProductResponse.from(repo.save(apply(new Product(),r)));} @Transactional public ProductResponse update(UUID id,ProductRequest r){var p=entity(id);repo.findByProductCode(r.productCode()).filter(x->!x.getId().equals(id)).ifPresent(x->{throw new ConflictException("Product code already exists");});return ProductResponse.from(repo.save(apply(p,r)));} public List<ProductResponse> all(){return repo.findAll().stream().map(ProductResponse::from).toList();} public ProductResponse get(UUID id){return ProductResponse.from(entity(id));}@Transactional public void delete(UUID id){var p=entity(id);p.setStatus(RecordStatus.INACTIVE);repo.save(p);} private Product apply(Product p,ProductRequest r){p.setCategory(r.categoryId()==null?null:cats.findById(r.categoryId()).orElseThrow(()->new ResourceNotFoundException("Product category not found: "+r.categoryId())));p.setProductCode(r.productCode());p.setName(r.name());p.setUnit(r.unit());p.setReferencePrice(r.referencePrice());p.setDescription(r.description());p.setStatus(r.status()==null?RecordStatus.ACTIVE:r.status());return p;}}
